"use client";

/**
 * Assistant home: a start screen with a greeting, an input and suggestion
 * chips. The chips fall away and the camera pushes into the input while the
 * prompt types itself.
 *
 * Written by Better Design. Painted from the theme prop, so the field's ring
 * and the spark in it take the product's primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, TextField, typed, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["400", "500", "600"], subsets: ["latin"] });

const FOCUS_AT = 34;
const FALL_AT = 40;
const PUSH_AT = 44;
const PUSH_FRAMES = 52;
const TYPE_AT = 54;
/** Frames the typing takes at most, however long the prompt is. */
const TYPE_BUDGET = 44;
const FIELD_W = 1000;
const FIELD_TOP = 478;
const FIELD_CY = FIELD_TOP + 42;
const MAX_ZOOM = 1.6;

export interface AssistantHomeProps {
  /** The large line above the input. */
  greeting?: string;
  /** The prompt that types into the input. Keep it to one short line. */
  prompt?: string;
  /** The chips under the input. They fall away as the prompt types. */
  suggestions?: string[];
  /** Grey text in the empty input. */
  placeholder?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function Spark({ color }: { color: string }) {
  return (
    <svg width={36} height={36} viewBox="0 0 24 24" fill={color}>
      <path d="M12 2.5c.5 4.6 2.9 7 9.5 9.5-6.6 2.5-9 4.9-9.5 9.5-.5-4.6-2.9-7-9.5-9.5 6.6-2.5 9-4.9 9.5-9.5z" />
    </svg>
  );
}

function Send({ theme, on }: { theme: VideoTheme; on: number }) {
  return (
    <div style={{ width: 60, height: 60, borderRadius: 30, flexShrink: 0, background: on > 0.5 ? theme.primary : theme.muted, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <svg width={28} height={28} viewBox="0 0 24 24" fill="none" stroke={on > 0.5 ? theme.primaryForeground : theme.mutedForeground} strokeWidth={2.6} strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 19V5M6 11l6-6 6 6" />
      </svg>
    </div>
  );
}

/** A start screen whose chips fall away while the camera pushes into the input. */
export function AssistantHome({
  greeting = "Good morning. What should we make?",
  prompt = "A pricing page for the team plan",
  suggestions = ["Plan a launch", "Summarise my notes", "Draft a reply", "Make a chart"],
  placeholder = "Ask anything",
  theme: themeOverride,
  font,
}: AssistantHomeProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const greet = easings.out(progress(frame, 0, 18));
  const field = easings.out(progress(frame, 8, 18));
  const push = easings.inOut(progress(frame, PUSH_AT, PUSH_FRAMES));
  const zoom = 1 + (MAX_ZOOM - 1) * push;
  const focusY = 540 + (FIELD_CY - 540) * push;
  const away = easings.in(progress(frame, PUSH_AT, 22));

  const cps = Math.max(22, (prompt.length / TYPE_BUDGET) * fps);
  const value = typed(prompt, frame, TYPE_AT, fps, cps);
  const state = frame < FOCUS_AT ? "idle" : frame >= TYPE_AT && value.length < prompt.length ? "typing" : "focused";

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 60% 50% at 50% 46%, ${withAlpha(theme.primary, 0.08)}, ${withAlpha(theme.primary, 0)} 70%)`,
          opacity: 1 - push * 0.5,
        }}
      />
      <AbsoluteFill style={{ transformOrigin: "0 0", transform: `translate(960px, 540px) scale(${zoom}) translate(-960px, ${-focusY}px)` }}>
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: 300,
            textAlign: "center",
            fontSize: 76,
            fontWeight: 600,
            letterSpacing: "-0.035em",
            color: theme.foreground,
            opacity: greet * (1 - away),
            transform: `translateY(${(1 - greet) * 20 - away * 40}px)`,
          }}
        >
          {greeting}
        </div>
        <div style={{ position: "absolute", left: (1920 - FIELD_W) / 2, top: FIELD_TOP, width: FIELD_W, opacity: field, transform: `translateY(${(1 - field) * 18}px)` }}>
          <TextField
            theme={theme}
            value={value}
            placeholder={placeholder}
            state={state}
            fontSize={36}
            fontFamily={family}
            leading={<Spark color={theme.primary} />}
            trailing={<Send theme={theme} on={value.length > 0 ? 1 : 0} />}
          />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: FIELD_TOP + 136, display: "flex", justifyContent: "center", gap: 18 }}>
          {suggestions.map((chip, i) => {
            const enter = easings.out(progress(frame, 16 + i * 3, 16));
            const fall = easings.in(progress(frame, FALL_AT + i * 3, 20));
            const side = i % 2 === 0 ? -1 : 1;
            return (
              <div
                key={`${chip}-${i}`}
                style={{
                  padding: "16px 28px",
                  borderRadius: 999,
                  background: theme.card,
                  border: `1px solid ${theme.border}`,
                  fontSize: 28,
                  fontWeight: 500,
                  color: theme.mutedForeground,
                  whiteSpace: "nowrap",
                  opacity: enter * (1 - Math.max(0, (fall - 0.4) / 0.6)),
                  transform: `translateY(${(1 - enter) * 16 + fall * 420}px) rotate(${side * fall * (10 + i * 3)}deg)`,
                }}
              >
                {chip}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
